-- STANDARD_INQUIRY_V2. Does not alter STANDARD_INQUIRY_V1 rows.

CREATE TYPE "PoMatchStatus" AS ENUM ('PENDING', 'MATCHED', 'MISMATCH');

ALTER TABLE "CommercialCommitment"
  ADD COLUMN "customerPoNumber" TEXT,
  ADD COLUMN "customerPoDate" TIMESTAMP(3),
  ADD COLUMN "customerPoDocumentRef" TEXT,
  ADD COLUMN "poValue" DECIMAL(65,30),
  ADD COLUMN "poCurrency" TEXT,
  ADD COLUMN "poMatchStatus" "PoMatchStatus",
  ADD COLUMN "poValidatedAt" TIMESTAMP(3),
  ADD COLUMN "poValidatedBy" TEXT,
  ADD COLUMN "poValidationNotes" TEXT,
  ADD COLUMN "foxOrderValidated" BOOLEAN NOT NULL DEFAULT false;

CREATE INDEX "CommercialCommitment_poMatchStatus_idx" ON "CommercialCommitment"("poMatchStatus");

SELECT
  'wf_tpl_standard_inquiry_v2',
  'STANDARD_INQUIRY_V2',
  1,
  'Standard Inquiry Workflow v2',
  'V1 path plus PO validation, explicit clarification loops, and FOX release steps. No generic engine.',
  'STANDARD_WORKFLOW',
  true,
  CURRENT_TIMESTAMP,
  CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM "WorkflowTemplate" WHERE "id" = 'wf_tpl_standard_inquiry_v2'
);


